var type=typeof(EchoSphere.Runtime.EchoSphereRuntime);var flags=System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic;var fields=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public;var nodeType=type.Assembly.GetType("EchoSphere.Presentation.NativeWorldNetwork+Node",true);int checks=0;
object Field(object value,string name)=>value.GetType().GetField(name,fields).GetValue(value);
EchoSphere.Presentation.V Shape(EchoSphere.Core.SphereNetworkShape shape)=>shape==null?EchoSphere.Presentation.VisualJs.Null:EchoSphere.Presentation.VisualJs.Obj("nodes",EchoSphere.Presentation.VisualJs.Arr(shape.NodeIndexes.Select(i=>new EchoSphere.Presentation.V(i)).ToArray()),"active",shape.Active);
string Key(object value){if(value==null)return "null";if(value is System.Array array)return string.Join("|",array.Cast<object>().Select(Key));if(value is int||value is bool)return value.ToString();return string.Join(";",value.GetType().GetFields(fields).OrderBy(f=>f.Name).Select(f=>f.Name+"="+Key(f.GetValue(value))));}
for(int count=0;count<=8;count++)foreach(double angle in new[]{0d,.73,1.13}){
 var nodes=Enumerable.Range(0,count).Select(i=>new EchoSphere.Core.SphereNetworkNode(new EchoSphere.Core.Vec2((float)Math.Cos(i*angle)*2.1f,(float)Math.Sin(i*angle)*2.1f))).ToList();var state=EchoSphere.Core.SphereNetworkRules.Analyze(nodes);
 var source=EchoSphere.Presentation.VisualJs.Obj("nodes",EchoSphere.Presentation.VisualJs.Arr(state.Nodes.Select(i=>new EchoSphere.Presentation.V(i)).ToArray()),"links",EchoSphere.Presentation.VisualJs.Arr(state.Links.Select(l=>EchoSphere.Presentation.VisualJs.Obj("a",l.A,"b",l.B)).ToArray()));foreach(EchoSphere.Core.SphereNetworkFormation kind in Enum.GetValues(typeof(EchoSphere.Core.SphereNetworkFormation)))if(kind!=EchoSphere.Core.SphereNetworkFormation.None)source[kind.ToString().ToLowerInvariant()]=Shape(state.GetFormation(kind));
 foreach(int sphereCount in new[]{0,count/2,count}){var array=Array.CreateInstance(nodeType,sphereCount);var spheres=EchoSphere.Presentation.VisualJs.Arr(Enumerable.Range(0,sphereCount).Select(i=>EchoSphere.Presentation.VisualJs.Obj("pos",EchoSphere.Presentation.VisualJs.Obj("x",0,"y",0))).ToArray());var scene=EchoSphere.Presentation.VisualJs.Obj("spheres",spheres,"minions",EchoSphere.Presentation.VisualJs.Arr(),"player",EchoSphere.Presentation.VisualJs.Obj("abilities",EchoSphere.Presentation.VisualJs.Obj()));var actual=type.GetMethod("ProjectNativeNetworkState",flags).Invoke(null,new object[]{state,array});var expected=type.GetMethod("ProjectNativeNetwork",flags).Invoke(null,new object[]{scene,source});var actualNetwork=Field(actual,"Item1");var expectedNetwork=Field(expected,"Item1");foreach(string name in new[]{"NodeCount","Links","Line","Triangle","Square","Cluster","Ring","Lattice","Fractal"}){if(Key(Field(actualNetwork,name))!=Key(Field(expectedNetwork,name)))throw new Exception("native network "+name+"/"+count+"/"+sphereCount);checks++;}if(Key(Field(actual,"Item2"))!=Key(Field(expected,"Item3")))throw new Exception("external links");checks++;}
}
